fn main() {
    let x = 5;
    // warning: unused variable: `x`
}

fn main() {
    let x = 5;
    x = 6; // error!
}

fn main() {
    let x: i32 = "hello"; // error!
}

fn main() {
    let x = 10;
    x = 20;          // Ошибка: неизменяемая переменная
    let y: i32 = "text"; // Ошибка: несоответствие типов
    println!(x);     // Ошибка: неверное использование макроса
}

fn main() {
    let unused = 42;
    let _also_unused = 100; // Префикс _ подавляет warning — компилятор поймёт, что переменная intentionally не используется
    println!("Done");
}
